  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;
  vec3 colBP = palette(x,
    vec3(0.55, 0.50, 0.58),
    vec3(0.25, 0.20, 0.28),
    vec3(1.00, 1.00, 1.00),
